local PatenMaker = {}
local PRODUCTS = {
    pewter_paten = { name = "Pustrasta patena", tinCost = 1, time = 1, cost = 20, sanctity = 3, description = "Pustrasta patena za hostijo." },
    brass_paten = { name = "Medeninasta patena", brassCost = 1, time = 2, cost = 50, sanctity = 6, prestige = 1, description = "Medeninasta patena z graviranim križem." },
    silver_paten = { name = "Srebrna patena", silverCost = 1, time = 4, cost = 140, sanctity = 10, prestige = 4, happiness = 1, description = "Srebrna patena z reliefom." },
    gold_paten = { name = "Zlata patena", goldCost = 1, silverCost = 1, time = 6, cost = 320, sanctity = 14, prestige = 10, happiness = 2, description = "Zlata patena za slovesne maše." },
    jewel_paten = { name = "Draguljna patena", goldCost = 2, silverCost = 1, jewelCost = 1, time = 9, cost = 700, sanctity = 19, prestige = 18, happiness = 4, description = "Patena z dragulji za katedralo." },
    royal_papal_paten = { name = "Kraljevski papeška patena", goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 1, time = 13, cost = 1800, sanctity = 30, prestige = 55, happiness = 11, description = "Velika kraljevska papeška patena z dragulji in biseri." },
}
local BUILDINGS = {
    workshop = { name = "Patenarska delavnica", cost = { gold = 270, wood = 110 }, upkeep = 6, qualityBonus = 5 },
    forge = { name = "Patenarska kovačija", cost = { gold = 800, wood = 200, stone = 180, silver = 6 }, upkeep = 18, qualityBonus = 18 },
    gilding_room = { name = "Pozlatnica", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, gold = 6 }, upkeep = 40, qualityBonus = 30 },
    royal_paten_atelier = { name = "Kraljevski atelje paten", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, jewel = 18 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
PatenMaker.tinStock = 12; PatenMaker.brassStock = 8; PatenMaker.silverStock = 8; PatenMaker.goldStock = 6; PatenMaker.jewelStock = 6; PatenMaker.pearlStock = 4
PatenMaker.productStock = {}; PatenMaker.buildings = {}; PatenMaker.maker = nil; PatenMaker.activeMaking = {}; PatenMaker.totalProducts = 0; PatenMaker.dayTimer = 0
function PatenMaker.init() PatenMaker.tinStock=12; PatenMaker.brassStock=8; PatenMaker.silverStock=8; PatenMaker.goldStock=6; PatenMaker.jewelStock=6; PatenMaker.pearlStock=4; PatenMaker.productStock={}; PatenMaker.buildings={}; PatenMaker.maker=nil; PatenMaker.activeMaking={}; PatenMaker.totalProducts=0; PatenMaker.dayTimer=0; print("[PatenMaker] Royal Paten Maker System initialized (6 products, 4 buildings)") end
function PatenMaker.hireMaker(n,s) s=s or math.random(50,90); local c=460+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PatenMaker.maker={name=n or ("Patenar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Patenar najet: %s (spretnost: %d)",PatenMaker.maker.name,s),"success") end; return true end
function PatenMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PatenMaker.build(id) local ok,e=PatenMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PatenMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PatenMaker.getQualityBonus() local b=0; for _,bd in ipairs(PatenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PatenMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.tinCost and PatenMaker.tinStock<(d.tinCost or 0) then return false,"Premalo kositra" end; if d.brassCost and PatenMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and PatenMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PatenMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PatenMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PatenMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PatenMaker.buildings==0 then return false,"Potrebna delavnica" end; if not PatenMaker.maker then return false,"Potreben patenar" end; return true end
function PatenMaker.make(pt,qty) qty=qty or 1; local ok,e=PatenMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.tinCost then PatenMaker.tinStock=PatenMaker.tinStock-d.tinCost*qty end; if d.brassCost then PatenMaker.brassStock=PatenMaker.brassStock-d.brassCost*qty end; if d.silverCost then PatenMaker.silverStock=PatenMaker.silverStock-d.silverCost*qty end; if d.goldCost then PatenMaker.goldStock=PatenMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PatenMaker.jewelStock=PatenMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PatenMaker.pearlStock=PatenMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PatenMaker.maker then t=math.max(1,t-math.floor(PatenMaker.maker.skill/12)) end; table.insert(PatenMaker.activeMaking,{id="paten_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,sanctity=d.sanctity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PatenMaker.completeMaking(m) local q=1.0+(PatenMaker.getQualityBonus()/100); if PatenMaker.maker then q=q+(PatenMaker.maker.skill/180) end; q=math.min(2.0,q); PatenMaker.productStock[m.productType]=(PatenMaker.productStock[m.productType] or 0)+m.quantity; PatenMaker.totalProducts=PatenMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PatenMaker.maker then PatenMaker.maker.itemsMade=PatenMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then PatenMaker.maker.skill=math.min(100,PatenMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Patena izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"paten.completed",{productName=m.productName,sanctity=m.sanctity}) end end
function PatenMaker.update(dt) if not _G.state then return end; PatenMaker.dayTimer=PatenMaker.dayTimer+dt; if PatenMaker.dayTimer>=30 then PatenMaker.dayTimer=0; for i=#PatenMaker.activeMaking,1,-1 do local m=PatenMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PatenMaker.completeMaking(m); table.remove(PatenMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PatenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PatenMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PatenMaker.getStats() return {tinStock=PatenMaker.tinStock,brassStock=PatenMaker.brassStock,silverStock=PatenMaker.silverStock,goldStock=PatenMaker.goldStock,jewelStock=PatenMaker.jewelStock,pearlStock=PatenMaker.pearlStock,productStock=PatenMaker.productStock,numBuildings=#PatenMaker.buildings,hasMaker=PatenMaker.maker~=nil,makerName=PatenMaker.maker and PatenMaker.maker.name or "—",makerSkill=PatenMaker.maker and PatenMaker.maker.skill or 0,activeMaking=#PatenMaker.activeMaking,totalProducts=PatenMaker.totalProducts} end
return PatenMaker
